<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import ConfirmationModal from '@/Components/ConfirmationModal.vue'; import InputError from '@/Components/InputError.vue'; import ValidationSummary from '@/Components/ValidationSummary.vue'; import {Head,useForm,router} from '@inertiajs/vue3'; import {reactive, ref} from 'vue';
const props=defineProps<{packages:any[];filters:any}>(); const filters=reactive({...props.filters}); const apply=()=>router.get(route('admin.packages.index'),filters,{preserveState:true,replace:true}); const reset=()=>{filters.search='';filters.active='';apply()}; const form=useForm({name:'',minimum_guests:1,maximum_guests:50,price:'',is_active:true}); const pendingPackage=ref<any>(null); const toggle=(item:any)=>{if(!item.is_active){pendingPackage.value=item;return;} updatePackage(item);}; const updatePackage=(item:any)=>router.put(route('admin.packages.update',item.id),{...item,is_active:!item.is_active},{onFinish:()=>pendingPackage.value=null});
</script>
<template><Head title="Packages"/><AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Packages</h2></template><div class="mx-auto max-w-5xl space-y-5 p-6"><form @submit.prevent="form.post(route('admin.packages.store'))" class="grid gap-2 bg-white p-4 shadow sm:grid-cols-5"><div><input v-model="form.name" placeholder="Name" required class="w-full rounded border-gray-300"><InputError :message="form.errors.name" class="mt-1"/></div><div><input v-model="form.minimum_guests" type="number" class="w-full rounded border-gray-300"><InputError :message="form.errors.minimum_guests" class="mt-1"/></div><div><input v-model="form.maximum_guests" type="number" class="w-full rounded border-gray-300"><InputError :message="form.errors.maximum_guests" class="mt-1"/></div><div><input v-model="form.price" type="number" placeholder="Price" class="w-full rounded border-gray-300"><InputError :message="form.errors.price" class="mt-1"/></div><button class="rounded bg-indigo-600 text-white">Add package</button><div class="sm:col-span-5"><ValidationSummary :errors="form.errors"/></div></form><form @submit.prevent="apply" class="flex gap-2"><input v-model="filters.search" placeholder="Search package name" class="rounded border-gray-300"><select v-model="filters.active" class="rounded border-gray-300"><option value="">All packages</option><option value="active">Active</option><option value="inactive">Inactive</option></select><button class="rounded bg-gray-800 px-3 text-white">Search</button><button type="button" @click="reset" class="text-gray-600">Reset</button></form><div class="bg-white shadow"><div v-for="packageItem in packages" :key="packageItem.id" class="flex justify-between border-b p-4"><span><b>{{packageItem.name}}</b> — Guest range: {{packageItem.minimum_guests}}–{{packageItem.maximum_guests}} — Price: <template v-if="packageItem.price !== null">${{packageItem.price}}</template><template v-else>Price not set</template> — {{packageItem.is_active?'Active':'Inactive'}}</span><button @click="toggle(packageItem)" class="text-indigo-600">{{packageItem.is_active?'Deactivate':'Activate'}}</button></div><p v-if="!packages.length" class="p-4 text-gray-600">No packages match your search or filter.</p></div></div><ConfirmationModal :show="!!pendingPackage" title="Deactivate package?" message="This package will no longer be available for new event assignments." confirm-label="Deactivate package" @close="pendingPackage=null" @confirm="updatePackage(pendingPackage)"/></AuthenticatedLayout></template>
